-- The three Egyptian God cards (902-904). They are drawn as full-card art
-- ("fullArt") and "locked": shown in the deck builder but no deck may hold
-- them until players earn access. Their effects are not in the engine yet.
-- A fresh database is seeded from cards.json after migrations run, so these
-- rows are only added to a catalog that is already there (card 0 exists).

INSERT OR IGNORE INTO cards (num, data, updated_at, updated_by) SELECT 902, '{"num":902,"name":"Obelisk the Tormentor","kind":"monster","deckCost":99,"type":"divine-beast","attribute":"divine","level":10,"atk":4000,"def":4000,"text":"Divine. To summon, sacrifice 3 of your monsters standing next to the same empty square: the God appears there face up. Ignores terrain. Only 1 God per deck. Sacrifice 2 of your monsters next to Obelisk to destroy every enemy monster in the 5x5 area around it; Obelisk cannot move or attack that turn. Enemy spells and traps cannot target it.","implemented":false,"image":"cards/902.jpg","custom":true,"locked":true,"fullArt":true}', strftime('%Y-%m-%dT%H:%M:%SZ','now'), 'migration' WHERE EXISTS (SELECT 1 FROM cards WHERE num = 0);
INSERT OR IGNORE INTO cards (num, data, updated_at, updated_by) SELECT 903, '{"num":903,"name":"Slifer the Sky Dragon","kind":"monster","deckCost":99,"type":"divine-beast","attribute":"divine","level":10,"atk":0,"def":0,"text":"Divine. To summon, sacrifice 3 of your monsters standing next to the same empty square: the God appears there face up. Ignores terrain. Only 1 God per deck. ATK and DEF are 1000 for each card in your hand. An enemy monster summoned, flipped face up or moved within 2 squares of Slifer loses 2000 ATK, and is destroyed if that brings it to 0.","implemented":false,"image":"cards/903.jpg","custom":true,"locked":true,"fullArt":true}', strftime('%Y-%m-%dT%H:%M:%SZ','now'), 'migration' WHERE EXISTS (SELECT 1 FROM cards WHERE num = 0);
INSERT OR IGNORE INTO cards (num, data, updated_at, updated_by) SELECT 904, '{"num":904,"name":"The Winged Dragon of Ra","kind":"monster","deckCost":99,"type":"divine-beast","attribute":"divine","level":10,"atk":0,"def":0,"text":"Divine. To summon, sacrifice 3 of your monsters standing next to the same empty square: the God appears there face up. Ignores terrain. Only 1 God per deck. When summoned, pay LP down to 100: Ra''s ATK and DEF become the LP paid. Pay 1000 LP to destroy an enemy monster in Ra''s line of sight (its row or column, nothing in between). Once, if Ra is destroyed, pay half your LP to revive it on its summon square.","implemented":false,"image":"cards/904.jpg","custom":true,"locked":true,"fullArt":true}', strftime('%Y-%m-%dT%H:%M:%SZ','now'), 'migration' WHERE EXISTS (SELECT 1 FROM cards WHERE num = 0);
